package dev.tacticalcombat.client.ui;

import com.google.gson.*;
import dev.tacticalcombat.client.*;
import net.minecraft.client.gui.DrawContext;
import net.minecraft.client.gui.screen.Screen;
import java.util.*;
import static dev.tacticalcombat.client.ui.ManagementState.*;
import static dev.tacticalcombat.uiapi.UiApiService.Operation.*;

/** Current authorized operations grouped into five sections; tabs store identities, not cached sheets. */
public final class DmWorkspaceScreen extends RpgScreen {
    private enum Section { PARTY, ACTORS, ENCOUNTERS, SCENE, ROLLS }
    private Section section=Section.PARTY;private final LinkedHashMap<String,String> tabs=new LinkedHashMap<>();
    private String inspection="";private JsonObject data;private CharacterCanvas canvas;private int y,page;private boolean refreshPending;
    public DmWorkspaceScreen(Screen parent){super("DM Workspace",parent);}
    @Override protected void init(){super.init();int w=Math.min(660,width-16),h=Math.min(470,height-16);frame=new UiLayout.Rect((width-w)/2,(height-h)/2,w,h);clearChildren();busy=false;data=null;footer();button("Refresh","",frame.x()+frame.width()-84,frame.y()+8,72,18,this::refresh);int sw=(frame.width()-24)/5;for(var s:Section.values())button(s.name().substring(0,1)+s.name().substring(1).toLowerCase(Locale.ROOT),"",frame.x()+12+s.ordinal()*sw,frame.y()+34,sw-3,20,()->{section=s;inspection="";client.setScreen(this);}).selected(section==s);build();refresh();}
    @Override protected void background(DrawContext g){RpgTheme.panel(g,frame.x(),frame.y(),frame.width(),frame.height(),0xED191D23,false);RpgTheme.text(g,textRenderer,getTitle().getString(),frame.x()+12,frame.y()+12,frame.width()-110,RpgTheme.GOLD);}
    private void refresh(){if(busy)return;data=null;build();request(!inspection.isEmpty()?QUICK_SHEET:section==Section.SCENE?ENCOUNTER_DISCOVER:DM_QUICK,!inspection.isEmpty()?args("character",inspection):section==Section.SCENE?args("binding","ALL","kind","ALL"):args("page",page),r->{if(r.code().equals("OK")){data=r.data();ClientRulesWatch.panel(this,UUID.fromString(text(data,"panelToken")),revoked->{if(client.currentScreen!=this)return;generation++;busy=false;data=null;if(revoked){tabs.clear();inspection="";}build();refreshPending=!revoked;message=revoked?"Manager access changed. Refresh to recheck.":"Campaign changed; refreshing…";});message="Current server-authorized workspace";}else{tabs.clear();inspection="";data=null;ClientRulesWatch.close(this);}build();});}
    private int w(){return canvas.getWidth()-16;}
    private void line(String text,int color){canvas.wrapped(text,8,y,w(),color);y+=Math.max(1,textRenderer.wrapLines(net.minecraft.text.Text.literal(text),w()).size())*12+6;}
    private void action(String title,String detail,Runnable task){canvas.control("action:"+y,new RpgButton(8,y,w(),detail.isEmpty()?22:36,title,detail,()->{if(!busy&&data!=null)task.run();}));y+=detail.isEmpty()?27:41;}
    private void inspect(String id,String name){if(!tabs.containsKey(id)&&tabs.size()>=6)tabs.remove(tabs.keySet().iterator().next());tabs.put(id,name);inspection=id;section=Section.PARTY;if(canvas!=null)canvas.position(0);refresh();}
    private void build(){if(frame==null)return;int offset=canvas==null?0:canvas.position();if(canvas!=null)remove(canvas);canvas=addDrawableChild(new CharacterCanvas(new UiLayout.Rect(frame.x()+6,frame.y()+60,frame.width()-12,Math.max(30,frame.height()-106))));y=4;if(data==null){line("Refresh to verify campaign manager access.",RpgTheme.MUTED);return;}
        if(!inspection.isEmpty()){
            int col=0,cw=w()/Math.min(3,Math.max(1,tabs.size()));for(var tab:tabs.entrySet()){int x=8+(col%3)*cw,ty=y+(col/3)*24;canvas.control("tab:"+tab.getKey(),new RpgButton(x,ty,cw-4,20,tab.getValue(),"",()->inspect(tab.getKey(),tab.getValue())).selected(inspection.equals(tab.getKey())));col++;}y+=((tabs.size()+2)/3)*24+4;
            y=CompactSheet.draw(canvas,data,y);action("Abilities, Skills & Saves","Validated character checks; unsupported grants explained",()->client.setScreen(new CharacterRollMenuScreen(this,data)));action("Full Character Sheet","",()->client.setScreen(PlayerNavigation.sheet(this,new DashboardSource(false,inspection))));action("Close this character tab","",()->{tabs.remove(inspection);inspection="";refresh();});action("Back to Party","",()->{inspection="";refresh();});canvas.position(offset);return;
        }
        line(text(data,"campaignName"),RpgTheme.GOLD);switch(section){
            case PARTY->{for(var tab:tabs.entrySet())action("Tab · "+tab.getValue(),"",()->inspect(tab.getKey(),tab.getValue()));for(var v:array(data,"characters")){var c=v.getAsJsonObject();action(text(c,"name")+(text(c,"health").isBlank()?"":" · "+text(c,"health"))+(text(c,"ac").isBlank()?"":" · AC "+text(c,"ac")),text(c,"kind")+" · "+(flag(c,"approved")?"Approved":"Needs approval")+" · "+text(c,"conditions"),()->inspect(text(c,"character"),text(c,"name")));}if(page>0)action("Previous","",()->{page--;refresh();});if(flag(data,"hasMore"))action("Next","",()->{page++;refresh();});action("Manage Characters","Approval, binding and advanced administration",()->client.setScreen(new CampaignRosterScreen(this,text(data,"campaign"))));}
            case ACTORS->{line("Find nearby actors, filter by binding/type, and bind approved campaign characters.",RpgTheme.TEXT);action("Nearby Actors & Quick Binding","Nearest first · 32 block radius",()->client.setScreen(new EncounterLauncherScreen(this,true)));action("SRD Monster Reference","Reference only; monster activation belongs to J2.5D",()->client.setScreen(new ReferenceCatalogScreen(this,"monsters")));}
            case ENCOUNTERS->{action("Start Encounter","Select 2–16 participants",()->client.setScreen(new EncounterLauncherScreen(this,true)));action("Manage Encounters","Watch initiative, open controls and end with confirmation",()->client.setScreen(new EncounterLauncherScreen(this,false)));if(ClientSrdCombat.hudEncounter()!=null){action("Watched Combat Controls","",()->client.setScreen(new SrdCombatScreen(this)));action("End Watched Encounter…","Persistent resources remain committed",()->client.setScreen(new RpgConfirmationScreen(this,"End encounter?","Committed D&D HP and ammunition remain saved.",()->request(ENCOUNTER_END,args("encounter",ClientSrdCombat.hudEncounter()),reply->{refreshPending=true;}))));}if(CubetableHud.MODEL.campaign().equals(text(data,"campaign")))for(var actor:CubetableHud.MODEL.actors())line((actor.active()?"▶ ":"")+actor.name()+" · initiative "+actor.initiative(),RpgTheme.TEXT);action("Gameplay Transaction Review","J2 prepared/committed outcomes and audited resolution",()->client.setScreen(new GameplayRecoveryScreen(this)));}
            case SCENE->{line("Encounter area preview · server discovery",RpgTheme.GOLD);int mapSize=Math.min(180,w());int mx=8+(w()-mapSize)/2,my=y;canvas.panel("N ↑ · 32-block radius",mx,my,mapSize,mapSize);double ox=data.get("originX").getAsDouble(),oz=data.get("originZ").getAsDouble();canvas.marker(mx+mapSize/2-3,my+mapSize/2-3,7,true);for(var value:array(data,"actors")){var actor=value.getAsJsonObject();int px=mx+mapSize/2+(int)((actor.get("x").getAsDouble()-ox)*(mapSize-20)/64),pz=my+mapSize/2+(int)((actor.get("z").getAsDouble()-oz)*(mapSize-20)/64);canvas.marker(px-3,pz-3,6,flag(actor,"eligible"));canvas.tooltip(px-4,pz-4,10,10,text(actor,"name")+" @ "+text(actor,"position")+" · "+text(actor,"reason"));}y+=mapSize+8;line("Current location: "+text(data,"location")+" · "+text(data,"dimension"),RpgTheme.TEXT);line("Discovery covers a 32-block sphere. Each selected actor uses its nearest supported same-height grid anchor. Occupied, obstructed or unsupported placement is rejected.",RpgTheme.TEXT);action("Inspect Starting Positions","Shows candidate coordinates and safe-anchor eligibility without moving actors",()->client.setScreen(new EncounterLauncherScreen(this,true)));line("Saved stages and persistent placement are planned for J2.5D. This view does not save templates or mutate the map.",RpgTheme.MUTED);}
            case ROLLS->{action("Character Checks & DM Requests","Individual/group requests, adjudication and private visibility",()->client.setScreen(new DmCheckScreen(this)));action("Check Requests & Results","Authorized pending and accepted session rolls",()->client.setScreen(new CheckInboxScreen(this)));action("Manual DM Dice","Server RNG · nearby/encounter audience · manual modifier",()->client.setScreen(new DiceToolbarScreen(this,true)));action("Authorized Dice & Event History","",()->client.setScreen(new HudLogScreen(this)));line("Manual rolls retain their nearby/encounter audience. Character Checks use separate authenticated permissions and visibility; no automatic combat effects.",RpgTheme.MUTED);}
        }action("Full Cubetable Menu","",()->client.setScreen(new HubScreen(this)));canvas.position(offset);
    }
    @Override public void tick(){super.tick();if(refreshPending&&!busy){refreshPending=false;refresh();}}
    @Override public boolean keyPressed(int key,int scan,int modifiers){if(TacticalCombatClient.DM_QUICK_KEY.matchesKey(key,scan)){close();return true;}return super.keyPressed(key,scan,modifiers);}
    @Override public void removed(){ClientRulesWatch.close(this);data=null;super.removed();}
}
